// The stable gowsdl SDK provides a SOAP client; it has no generated server entrypoint.
package main

import (
	"context"
	"net/http"
	"time"

	"github.com/hooklift/gowsdl/soap"
	"meteor.test/orderpeer/gen/soapecho"
)

func callSoapPeer(opts options) (string, error) {
	// Use the committed client generated by gowsdl v0.5.0 from the shared Echo WSDL and XSD.
	transport := &http.Transport{}
	defer transport.CloseIdleConnections()
	httpClient := &http.Client{Transport: transport, Timeout: 10 * time.Second}
	client := soap.NewClient(opts.target, soap.WithHTTPClient(httpClient))
	service := soapecho.NewEchoPortType(client)
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	// The official SDK owns the SOAP envelope and action; the business call is an ordinary text echo.
	response, err := service.EchoContext(ctx, &soapecho.Echo{Message: textSample})
	if err != nil {
		return "", err
	}
	return response.Result, nil
}
